    let articleImages = [];
    let touchStartX = 0;
    let touchEndX = 0;

    // pies de foto de las imagenes del articulo: fuente confiable del cms
    const articleImageMetas = [{"src":"https://www.jornada.com.mx/ndjsimg/images/jornada/jornadaimg/urgente-e-imperativo-poner-fin-al-bloqueo-de-eu-contra-cuba-dice-embajador-vasconcelos-ante-la-onu/urgente-e-imperativo-poner-fin-al-bloqueo-de-eu-contra-cuba-dice-embajador-vasconcelos-ante-la-onu_70c221f3-c44c-4725-8250-cda5a74a70ff_media","caption":"El embajador y representante de México ante la ONU, Héctor Vasconcelos.  Imagen https://x.com/HVasconcelos_"}];

    // obtener el pie de foto de una imagen del articulo
    function obtenerPieFoto(imgElement) {
        const parentFigure = imgElement.closest('figure');
        if (parentFigure) {
            const figCaption = parentFigure.querySelector('figcaption');
            if (figCaption) {
                const texto = figCaption.innerHTML.trim();
                if (texto) return texto;
            }
        }
        const meta = articleImageMetas.find(m => m.src && imgElement.src && imgElement.src.indexOf(m.src) !== -1);
        if (meta && meta.caption) return meta.caption;
        return imgElement.alt || imgElement.title || '';
    }

    // Función para inicializar las imágenes del artículo
    document.addEventListener('DOMContentLoaded', function() {
        // Obtener todas las imágenes dentro del contenido del artículo
        articleImages = Array.from(document.querySelectorAll('#content_nitf img.article-image'));

        // Inicializar gestos táctiles
        initTouchEvents();
    });

    // Inicializar eventos táctiles
    function initTouchEvents() {
        const overlay = document.getElementById('fullscreenOverlay');

        // Evento de inicio de toque
        overlay.addEventListener('touchstart', function(e) {
            touchStartX = e.changedTouches[0].screenX;
        }, false);

        // Evento de fin de toque
        overlay.addEventListener('touchend', function(e) {
            touchEndX = e.changedTouches[0].screenX;
            handleSwipe();
        }, false);
    }

    // Manejar el gesto de deslizar
