    // Abrir imagen en pantalla completa
    function openFullScreen(imgElement) {
        const overlay = document.getElementById('fullscreenOverlay');
        const fullscreenImg = document.getElementById('fullscreenImage');
        const caption = document.getElementById('fullscreenCaption');
        const prevButton = document.getElementById('prevButton');
        const nextButton = document.getElementById('nextButton');

        // Encontrar el índice de la imagen actual
        currentImageIndex = articleImages.indexOf(imgElement);

        // Establecer la imagen y el pie de foto
        fullscreenImg.src = imgElement.src;

        // Obtener el pie de foto y mostrarlo si existe
        const captionText = obtenerPieFoto(imgElement);
        caption.innerHTML = captionText;
        caption.style.display = captionText ? 'block' : 'none';

        // Ocultar botones de navegación si solo hay una imagen
        if (articleImages.length  1 && !localStorage.getItem('swipeInstructionShown')) {
            showSwipeInstructions();
            localStorage.setItem('swipeInstructionShown', 'true');
        }
    }

