    // Cerrar pantalla completa
    function closeFullScreen() {
        const overlay = document.getElementById('fullscreenOverlay');
        overlay.style.display = 'none';

        // Restaurar scroll
        document.body.style.overflow = 'auto';
    }

    // Navegar entre imágenes
    function navigateImages(direction) {
        if (articleImages.length = articleImages.length) {
            currentImageIndex = 0;
        }

        const imgElement = articleImages[currentImageIndex];
        const fullscreenImg = document.getElementById('fullscreenImage');
        const caption = document.getElementById('fullscreenCaption');

        // Cambiar la imagen actual con efecto de transición
        fullscreenImg.style.opacity = '0.3';
        setTimeout(() => {
            // Cambiar la imagen actual
            fullscreenImg.src = imgElement.src;
            fullscreenImg.style.opacity = '1';

            // Actualizar el pie de foto
            const captionText = obtenerPieFoto(imgElement);
            caption.innerHTML = captionText;
            caption.style.display = captionText ? 'block' : 'none';
        }, 200);
    }

    // Permitir cerrar con Escape y navegar con flechas
    document.addEventListener('keydown', function(event) {
        if (event.key === 'Escape') {
            closeFullScreen();
        } else if (event.key === 'ArrowLeft') {
            navigateImages(-1);
        } else if (event.key === 'ArrowRight') {
            navigateImages(1);
        }
    });


