    video {
        max-width: 100%;
        height: auto;
    }
    .nota-justify {
        text-align: justify;
    }
    .nota-left {
        text-align: left;
    }
    .nota-right {
        text-align: right;
    }

    /* Estilos para imágenes a pantalla completa */
    .article-image {
        cursor: pointer;
        transition: transform 0.3s ease;
        max-width: 100%; /* Asegura que las imágenes no desborden su contenedor */
    }

    .article-image:hover {
        transform: scale(1.02);
    }

    .fullscreen-overlay {
        display: none;
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 0, 0, 0.95);
        z-index: 9999;
        justify-content: center;
        align-items: center;
        flex-direction: column;
        touch-action: none; /* Previene desplazamiento en dispositivos táctiles */
    }

    .fullscreen-image {
        max-width: 95%;
        max-height: calc(100vh - 180px) !important;
        object-fit: contain;
        user-select: none; /* Previene la selección de imagen */
        -webkit-user-select: none;
        -webkit-touch-callout: none; /* Previene menú contextual en iOS */
        transition: opacity 0.2s ease;
    }

    .fullscreen-caption {
        color: white;
        font-size: 14px;
        margin-top: 15px;
        margin-bottom: 40px;
        padding: 0 20px;
        text-align: center;
        width: 90%;
        max-width: 600px;
        box-sizing: border-box;
    }

    .close-button {
        position: absolute;
        top: 15px;
        right: 15px;
        color: white;
        font-size: 28px;
        cursor: pointer;
        background: rgba(0, 0, 0, 0.3);
        border: none;
        width: 44px;
        height: 44px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        z-index: 10001;
    }

    .navigation-button {
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        color: white;
        font-size: 24px;
        cursor: pointer;
        background-color: rgba(0, 0, 0, 0.4);
        border: none;
        width: 44px;
        height: 60px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 5px;
        z-index: 10000;
        transition: background-color 0.2s ease;
    }

    .navigation-button:hover {
        background-color: rgba(0, 0, 0, 0.7);
    }

    .prev-button {
        left: 10px;
    }

    .next-button {
        right: 10px;
    }

    /* Ajustes específicos para móviles */
    @media (max-width: 768px) {
        .fullscreen-image {
            max-width: 100%;
            max-height: calc(100vh - 150px) !important;
        }

        .navigation-button {
            width: 40px;
            height: 50px;
            font-size: 20px;
        }

        .prev-button {
            left: 5px;
        }

        .next-button {
            right: 5px;
        }

        .close-button {
            top: 10px;
            right: 10px;
            width: 36px;
            height: 36px;
            font-size: 24px;
        }

        .fullscreen-caption {
            font-size: 12px;
            margin-top: 10px;
            margin-bottom: 30px;
            width: 100%;
            padding: 0 15px;
        }
    }

    /* Soporte para gestos táctiles en móviles */
    @media (hover: none) {
        .article-image:hover {
            transform: none; /* Desactiva el efecto hover en dispositivos táctiles */
        }
    }

    /* Soporte para orientación horizontal en móviles */
    @media (max-height: 500px) and (orientation: landscape) {
        .fullscreen-image {
            max-height: calc(100vh - 120px);
        }

        .fullscreen-caption {
            margin-top: 5px;
            margin-bottom: 20px;
            font-size: 11px;
        }

        .close-button {
            top: 5px;
            right: 5px;
        }
    }

    /* Soporte para pantallas muy pequeñas */
    @media (max-width: 320px) {
        .navigation-button {
            width: 36px;
            height: 40px;
            font-size: 18px;
        }

        .close-button {
            width: 32px;
            height: 32px;
            font-size: 20px;
        }
    }












